package br.com.essenciaviva.ui;
import br.com.essenciaviva.config.Database; import br.com.essenciaviva.security.Crypto; import br.com.essenciaviva.security.Session;
import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.sql.*; import java.time.LocalDate; import java.util.regex.Pattern;

public class MainFrame extends JFrame {
    private final Session session; private final JTabbedPane tabs=new JTabbedPane(); private final Timer timer; private boolean warningShown;
    public MainFrame(Session session){this.session=session; setTitle("Essência Viva - Clínica Estética"); setSize(1000,650); setLocationRelativeTo(null); setDefaultCloseOperation(EXIT_ON_CLOSE); add(tabs); tabs.addTab("Clientes",clients()); tabs.addTab("Profissionais",simple("profissional",new String[]{"nome","registro","especialidade"})); tabs.addTab("Procedimentos",simple("procedimento",new String[]{"nome","descricao","duracao_minutos","valor"})); tabs.addTab("Agendamentos",appointments()); JButton sair=new JButton("Sair"); sair.addActionListener(e->{session.close();dispose();new LoginFrame().setVisible(true);}); add(sair,BorderLayout.SOUTH); timer=new Timer(10000,e->checkSession()); timer.start(); }
    private void checkSession(){ if(session.expired()){timer.stop();session.close();JOptionPane.showMessageDialog(this,"Sua sessão foi encerrada por inatividade. Faça login novamente.");dispose();new LoginFrame().setVisible(true); return;} if(session.secondsToExpire()<=60&&!warningShown){warningShown=true;int answer=JOptionPane.showConfirmDialog(this,"Sua sessão vai expirar em menos de 1 minuto. Continuar conectado?","Sessão",JOptionPane.YES_NO_OPTION);if(answer==JOptionPane.YES_OPTION){try{session.touch();warningShown=false;}catch(SQLException ignored){}}} try{session.touch();}catch(SQLException ignored){} }
    private JPanel clients(){ JPanel p=new JPanel(new BorderLayout()); DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Nome","CPF","Status"},0); JTable t=new JTable(m); p.add(new JScrollPane(t)); loadClients(m); JPanel form=new JPanel(new GridLayout(2,6,5,5)); JTextField nome=new JTextField(),cpf=new JTextField(),nasc=new JTextField(),tel=new JTextField(),email=new JTextField(),end=new JTextField(); JButton add=new JButton("Cadastrar cliente"); for(JTextField f:new JTextField[]{nome,cpf,nasc,tel,email,end})form.add(f); form.add(add); p.add(form,BorderLayout.SOUTH); add.addActionListener(e->{if(nome.getText().isBlank()||!cpf.getText().matches("\\d{11}")){JOptionPane.showMessageDialog(this,"Informe nome e CPF com 11 dígitos.");return;}try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement("INSERT INTO cliente(nome,cpf_hash,cpf_cifrado,nascimento_cif,telefone_cif,email_cif,endereco_cif) VALUES(?,?,?,?,?,?,?)")){q.setString(1,nome.getText());q.setString(2,Crypto.hmac(cpf.getText()));q.setString(3,Crypto.encrypt(cpf.getText()));q.setString(4,Crypto.encrypt(nasc.getText()));q.setString(5,Crypto.encrypt(tel.getText()));q.setString(6,Crypto.encrypt(email.getText()));q.setString(7,Crypto.encrypt(end.getText()));q.executeUpdate();loadClients(m);JOptionPane.showMessageDialog(this,"Cliente cadastrado.");}catch(SQLException ex){JOptionPane.showMessageDialog(this,"CPF já cadastrado ou banco indisponível.");}});return p; }
    private void loadClients(DefaultTableModel m){m.setRowCount(0);try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,nome,cpf_cifrado,status FROM cliente ORDER BY nome")){while(r.next()){String cpf=Crypto.decrypt(r.getString(3));m.addRow(new Object[]{r.getInt(1),r.getString(2),"***."+cpf.substring(3,6)+"."+cpf.substring(6,9)+"-"+cpf.substring(9),r.getString(4)});}}catch(Exception ignored){}}
    private JPanel simple(String table,String[] fields){JPanel p=new JPanel(new BorderLayout());DefaultTableModel m=new DefaultTableModel(fields,0);JTable t=new JTable(m);p.add(new JScrollPane(t));JTextField[] inputs=new JTextField[fields.length];JPanel f=new JPanel(new GridLayout(2,fields.length+1,5,5));for(int i=0;i<fields.length;i++){inputs[i]=new JTextField();f.add(inputs[i]);}JButton b=new JButton("Cadastrar");f.add(b);p.add(f,BorderLayout.SOUTH);loadSimple(table,fields,m);b.addActionListener(e->{try(Connection c=Database.getConnection()){String cols=String.join(",",fields);String marks=String.join(",",java.util.Collections.nCopies(fields.length,"?"));try(PreparedStatement q=c.prepareStatement("INSERT INTO "+table+"("+cols+") VALUES("+marks+")")){for(int i=0;i<inputs.length;i++)q.setString(i+1,inputs[i].getText());q.executeUpdate();loadSimple(table,fields,m);}}catch(SQLException ex){JOptionPane.showMessageDialog(this,"Preencha os campos corretamente.");}});return p;}
    private void loadSimple(String table,String[] fields,DefaultTableModel m){m.setRowCount(0);try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT "+String.join(",",fields)+" FROM "+table)){while(r.next()){Object[] row=new Object[fields.length];for(int i=0;i<fields.length;i++)row[i]=r.getObject(i+1);m.addRow(row);}}catch(SQLException ignored){}}
    private JPanel appointments(){JPanel p=new JPanel(new BorderLayout());p.add(new JLabel("Novo agendamento (informe IDs e horários no formato HH:mm)."),BorderLayout.NORTH);DefaultTableModel m=new DefaultTableModel(new String[]{"Cliente","Profissional","Data","Início","Fim","Situação"},0);p.add(new JScrollPane(m),BorderLayout.CENTER);JPanel f=new JPanel(new GridLayout(2,7,4,4));JTextField cliente=new JTextField(),profissional=new JTextField(),data=new JTextField(LocalDate.now().toString()),inicio=new JTextField("09:00"),fim=new JTextField("10:00"),situacao=new JTextField("agendado");JButton salvar=new JButton("Agendar");for(JTextField x:new JTextField[]{cliente,profissional,data,inicio,fim,situacao})f.add(x);f.add(salvar);p.add(f,BorderLayout.SOUTH);loadAppointments(m);salvar.addActionListener(e->{try(Connection c=Database.getConnection()){String conflito="SELECT COUNT(*) FROM agendamento WHERE profissional_id=? AND data_atendimento=? AND situacao='agendado' AND hora_inicio < ? AND hora_fim > ?";try(PreparedStatement v=c.prepareStatement(conflito)){v.setInt(1,Integer.parseInt(profissional.getText()));v.setDate(2,Date.valueOf(data.getText()));v.setTime(3,Time.valueOf(inicio.getText()+":00"));v.setTime(4,Time.valueOf(fim.getText()+":00"));try(ResultSet r=v.executeQuery()){r.next();if(r.getInt(1)>0){JOptionPane.showMessageDialog(this,"Esse profissional já possui atendimento nesse horário.");return;}}}try(PreparedStatement q=c.prepareStatement("INSERT INTO agendamento(cliente_id,profissional_id,data_atendimento,hora_inicio,hora_fim,situacao,valor_total) VALUES(?,?,?,?,?,?,0)")){q.setInt(1,Integer.parseInt(cliente.getText()));q.setInt(2,Integer.parseInt(profissional.getText()));q.setDate(3,Date.valueOf(data.getText()));q.setTime(4,Time.valueOf(inicio.getText()+":00"));q.setTime(5,Time.valueOf(fim.getText()+":00"));q.setString(6,situacao.getText());q.executeUpdate();loadAppointments(m);}}catch(Exception ex){JOptionPane.showMessageDialog(this,"Confira IDs, data e horários.");}});return p;}
    private void loadAppointments(DefaultTableModel m){m.setRowCount(0);try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT cliente_id,profissional_id,data_atendimento,hora_inicio,hora_fim,situacao FROM agendamento ORDER BY data_atendimento,hora_inicio")){while(r.next())m.addRow(new Object[]{r.getInt(1),r.getInt(2),r.getDate(3),r.getTime(4),r.getTime(5),r.getString(6)});}catch(SQLException ignored){}}
}
